facts=[dict(id='F-quorum-index',meaning='Within this commitment object, commitIndex is the largest quorum order statistic accepted so far after reaching startIndex, computed from configured voter match indexes. This is support accounting, not completed FSM application.',identity={'owner':'commitment object for leadership tenure','entry':'log index'},validity_context='Current configuration voter map within one tenure; retained voter IDs keep match indexes across setConfiguration.',representation=['commitment.matchIndexes','commitment.commitIndex','commitment.startIndex'],invalidators=['B-tenure'],reinterpreters=['B-membership'],durability='Volatile aggregation; log and snapshot data supplying matches use injected stores.',recovery='Recreated with zero match indexes at each new tenure; replication reconstructs support.',source_ids=['M-commit','M-leader','M-update','M-snapshot-send'],unknowns=[]),dict(id='F-verify-support',meaning='A verifyFuture records self plus successful worker notifications against a threshold derived from voter count. When the tally reaches threshold, or any negative notification arrives, the future is queued once for main-loop completion. The tally itself does not encode voter identity or establish continued cluster authority.',identity={'operation':'verifyFuture pointer','owner':'leader tenure pending notify set'},validity_context='From registration until result scheduling/cleanup; worker notifications can arise from append, heartbeat or snapshot responses.',representation=['verifyFuture.votes','verifyFuture.quorumSize','verifyFuture.notifyCh','followerReplication.notify'],invalidators=['B-tenure','B-verify-finish'],reinterpreters=[],durability='Volatile per-operation state.',recovery='Not restored; callers must issue a new verification after prior operation/tenure ends.',source_ids=['M-verify','M-notify','M-verify-vote','M-leader-loop','M-leader'],unknowns=['A quorum-sized count can contain nonvoter notifications; whether source-authorized histories make its successful consumption unsafe remains to be checked.'])]
